#
# Clock-and-reset generator for the Colorlight i9plus + USB3300 ULPI setup.
# Single USB device, no audio PLL yet — that comes when we wire I2S or
# bring over the AVB stack.
#
# Clock domains:
#   sync : main fabric clock. clk25 × 12 ÷ 5 = 60 MHz from the on-board PLL.
#   usb  : 60 MHz sourced directly from ULPI_CLK (driven by the USB3300).
#   fast : 240 MHz, present because the LUNA USB stack derives some
#          DDR ULPI paths from it. Generated by the same PLL.
#
# When we add audio later, a second PLL can generate audio_clk from the
# main 25 MHz input — keeping that PLL separate from the USB one avoids
# coupling re-locks during MMCM DRP retuning of the audio rate.

from amaranth import Module, Elaboratable, ClockDomain, Signal, Instance, ResetSignal
from amaranth.lib.cdc import ResetSynchronizer


class ColorlightI9PlusCAR(Elaboratable):
    """Clock domain generator for Colorlight i9plus + USB3300 ULPI.

    The top-level Elaboratable requests both `ulpi` and `clk25`, then
    passes the ulpi.clk pin to this CAR's constructor. We can't
    `platform.request("ulpi", 0)` here because LUNA's USBDevice in the
    top-level requests it first.

    Used as `platform.clock_domain_generator(ulpi_clk_pin=...)` from
    the top-level. The kwargs match LUNA's calling convention plus our
    ulpi_clk_pin extension.
    """

    def __init__(self, *, ulpi_clk_pin=None, usb_phase=-120.0, usb_pll=True,
                 usb_invert=False, ulpi_clk_pin_b=None,
                 usb_phase_b=None, usb_pll_b=None, usb_invert_b=None,
                 clock_frequencies=None, clock_signal_name=None):
        # LUNA passes clock_frequencies/clock_signal_name but we don't
        # use them; ulpi_clk_pin is OUR addition — the top-level provides
        # the already-requested ulpi.clk subsignal.
        self.ulpi_clk_pin = ulpi_clk_pin
        # ulpi_clk_pin_b: a SECOND, INDEPENDENT ULPI clock, for running both
        # USB3300s from one bitstream. The two PHYs have their own crystals --
        # measured 60,006,601 Hz (A) vs 60,002,287 Hz (B), 72 ppm apart -- so
        # cd_usb and cd_usb_b are genuinely asynchronous domains and anything
        # crossing between them needs a CDC. The *_b options default to the
        # corresponding A option so the second PHY gets the identical proven
        # recipe unless deliberately overridden.
        self.ulpi_clk_pin_b = ulpi_clk_pin_b
        self.usb_phase_b  = usb_phase  if usb_phase_b  is None else usb_phase_b
        self.usb_pll_b    = usb_pll    if usb_pll_b    is None else usb_pll_b
        self.usb_invert_b = usb_invert if usb_invert_b is None else usb_invert_b
        self.usb_phase    = usb_phase
        # usb_pll=False → drive cd_usb.clk straight from the ULPI clock
        # pin (tools insert a BUFG). Matches ultraembedded's validated
        # Spartan-6 setup (raw PHY clock, no PLL). usb_pll=True → run
        # the ULPI clock through a phase-shifting PLL.
        self.usb_pll      = usb_pll
        # usb_invert=True → cd_usb runs on the inverted ULPI clock
        # (falling edge). Only meaningful when usb_pll=False.
        self.usb_invert   = usb_invert

    def elaborate(self, platform):
        m = Module()

        cd_sync  = ClockDomain("sync")
        cd_usb   = ClockDomain("usb")
        cd_fast  = ClockDomain("fast")
        cd_audio = ClockDomain("audio")          # ~12.288 MHz for the I2S DAC
        m.domains += [cd_sync, cd_usb, cd_fast, cd_audio]
        cd_usb_b = None
        if self.ulpi_clk_pin_b is not None:
            cd_usb_b = ClockDomain("usb_b")
            m.domains += [cd_usb_b]

        clk25 = platform.request(platform.default_clk, 0)

        # --- Main PLL: clk25 → 60 MHz (sync) + 240 MHz (fast) ---
        # VCO = 25 × 24 = 600 MHz. clkout0 = 600/10 = 60 MHz. clkout1 = 600/2.5 = 240 MHz.
        # PLLE2_ADV is the Artix-7 PLL primitive (less capable than MMCM but
        # sufficient for our single VCO + two outputs).
        mainpll_feedback = Signal()
        sys_clk          = Signal()
        fast_clk         = Signal()
        audio_clk        = Signal()
        sys_locked       = Signal()

        m.submodules.mainpll = Instance("PLLE2_ADV",
            p_BANDWIDTH       = "OPTIMIZED",
            # "INTERNAL" is what nextpnr-xilinx's fasm backend supports;
            # "ZHOLD" (Vivado default) crashes the open toolchain at
            # post-routing legalisation (fasm.cc:1572).
            p_COMPENSATION    = "INTERNAL",
            p_STARTUP_WAIT    = "FALSE",
            p_DIVCLK_DIVIDE   = 1,
            # VCO must be 800-1600 MHz on XC7A50T-1 (UG472). Previous
            # MULT=24 gave VCO=600 MHz — out of spec; PLL output was
            # undefined.  MULT=48 → VCO = 25 × 48 = 1200 MHz (well in
            # spec) gives clean integer dividers for 60 / 200 MHz.
            p_CLKFBOUT_MULT   = 48,
            p_CLKFBOUT_PHASE  = 0.0,
            p_CLKIN1_PERIOD   = 40.0,            # clk25 → 40 ns period

            p_CLKOUT0_DIVIDE  = 20,              # 1200 / 20 = 60 MHz (sync)
            p_CLKOUT0_PHASE   = 0.0,
            p_CLKOUT0_DUTY_CYCLE = 0.5,

            p_CLKOUT1_DIVIDE  = 6,               # 1200 / 6 = 200 MHz (fast)
            p_CLKOUT1_PHASE   = 0.0,
            p_CLKOUT1_DUTY_CYCLE = 0.5,

            # 1200 / 98 = 12.245 MHz ≈ 256 × 47.8 kHz — the I2S DAC clock. Slight
            # (0.35%) offset from 12.288 MHz is fine for a monitor: BCK = /4,
            # LRCK = /256 are derived as pure integer divides → clean, exactly
            # 32 BCK/channel (the DAC needs a clean BCK, not exact fs).
            p_CLKOUT2_DIVIDE  = 98,
            p_CLKOUT2_PHASE   = 0.0,
            p_CLKOUT2_DUTY_CYCLE = 0.5,

            i_CLKIN1   = clk25.i,
            i_CLKFBIN  = mainpll_feedback,
            o_CLKFBOUT = mainpll_feedback,
            o_CLKOUT0  = sys_clk,
            o_CLKOUT1  = fast_clk,
            o_CLKOUT2  = audio_clk,
            o_LOCKED   = sys_locked,
        )

        # USB-PLL: take ULPI CLK input (60 MHz from PHY) and re-emit
        # 60 MHz with a phase shift. Mirrors LiteX terasic_deca _CRG
        # pattern (validated with LUNA): pll.create_clkout(usb, 60e6,
        # phase=-120). The phase shift aligns the FPGA's sampling
        # edge inside the ULPI data valid window — without it, the
        # LUNA register-window FSM exits IDLE briefly but never
        # completes a write because the data sampled by IOB flops is
        # past its valid window.
        #
        # PLLE2_ADV constraints: VCO 800-1600 MHz on Artix-7 -1 speed.
        # Use CLKFBOUT_MULT=16 (VCO = 60 × 16 = 960 MHz), CLKOUT0_DIVIDE=16
        # (60 MHz out), CLKOUT0_PHASE=-120.
        m.d.comb += [
            cd_sync.clk.eq(sys_clk),
            cd_fast.clk.eq(fast_clk),
            cd_audio.clk.eq(audio_clk),
        ]

        def _usb_clock(pin, phase, use_pll, invert, tag):
            """Build one ULPI-derived 60 MHz clock. `tag` uniquifies the
            submodule names so this can be called once per PHY. The body is
            the original single-PHY code verbatim -- see the long notes below
            for why the BUFG before CLKIN is mandatory."""
            if use_pll:
                fb = Signal(name=f"usbpll_fb{tag}")
                out = Signal(name=f"usb_clk_pll{tag}")
                locked = Signal(name=f"usb_pll_locked{tag}")
                clkin_buf = Signal(name=f"usb_clkin_buf{tag}")
                m.submodules[f"usb_clkin_bufg{tag}"] = Instance(
                    "BUFG", i_I=pin, o_O=clkin_buf)
                m.submodules[f"usbpll{tag}"] = Instance("PLLE2_ADV",
                    p_BANDWIDTH="OPTIMIZED", p_COMPENSATION="INTERNAL",
                    p_STARTUP_WAIT="FALSE", p_DIVCLK_DIVIDE=1,
                    p_CLKFBOUT_MULT=16, p_CLKFBOUT_PHASE=0.0,
                    p_CLKIN1_PERIOD=16.667, p_CLKOUT0_DIVIDE=16,
                    p_CLKOUT0_PHASE=phase, p_CLKOUT0_DUTY_CYCLE=0.5,
                    i_CLKIN1=clkin_buf, i_CLKFBIN=fb, o_CLKFBOUT=fb,
                    o_CLKOUT0=out, o_LOCKED=locked)
                return out
            elif invert:
                return ~pin
            else:
                return pin

        if cd_usb_b is not None:
            m.d.comb += cd_usb_b.clk.eq(_usb_clock(
                self.ulpi_clk_pin_b, self.usb_phase_b, self.usb_pll_b,
                self.usb_invert_b, "_b"))

        if self.usb_pll:
            usbpll_feedback = Signal()
            usb_clk_pll     = Signal()
            usb_pll_locked  = Signal()
            # Route the ULPI clock through an EXPLICIT global buffer (BUFG)
            # BEFORE the PLL CLKIN. A 7-series PLLE2 accepts a *direct*
            # pin->CLKIN route ONLY from a clock-capable pin in the PLL's own
            # clock region. Main's CLK (T4, bank 34) lands in-region so the
            # direct connection works; the Backup CLK (W19, bank 14, P3 header)
            # is in a DIFFERENT clock region, so the direct route is invalid and
            # the PLL never locks -> solid LED even with a clean 60 MHz present
            # at W19 (proven by the BUFG-based clock-test, which works on both
            # pins because a BUFG reaches every region). A BUFG output is global,
            # so feeding CLKIN from it lets the PLL lock from either bank.
            # nextpnr-xilinx does NOT reliably auto-insert this buffer, so it is
            # explicit. (2026-09-09, backup-USB P3 bring-up.)
            usb_clkin_buf = Signal()
            m.submodules.usb_clkin_bufg = Instance(
                "BUFG", i_I=self.ulpi_clk_pin, o_O=usb_clkin_buf)
            m.submodules.usbpll = Instance("PLLE2_ADV",
                p_BANDWIDTH         = "OPTIMIZED",
                p_COMPENSATION      = "INTERNAL",
                p_STARTUP_WAIT      = "FALSE",
                p_DIVCLK_DIVIDE     = 1,
                p_CLKFBOUT_MULT     = 16,
                p_CLKFBOUT_PHASE    = 0.0,
                p_CLKIN1_PERIOD     = 16.667,        # 60 MHz period
                p_CLKOUT0_DIVIDE    = 16,
                p_CLKOUT0_PHASE     = self.usb_phase,
                p_CLKOUT0_DUTY_CYCLE= 0.5,
                i_CLKIN1   = usb_clkin_buf,
                i_CLKFBIN  = usbpll_feedback,
                o_CLKFBOUT = usbpll_feedback,
                o_CLKOUT0  = usb_clk_pll,
                o_LOCKED   = usb_pll_locked,
            )
            m.d.comb += cd_usb.clk.eq(usb_clk_pll)
        elif self.usb_invert:
            # Inverted ULPI clock → whole usb domain runs on the PHY's
            # falling edge. Shifts BOTH input sampling and output driving
            # by half a 60 MHz period (~8.3 ns), compensating the
            # PHY↔FPGA round-trip skew in both directions at once. This
            # is the Sipeed Tang Primer 20K `~ulpi_clk` recipe.
            m.d.comb += cd_usb.clk.eq(~self.ulpi_clk_pin)
        else:
            # Raw ULPI clock straight to the usb domain. The tools
            # insert a BUFG. Matches ultraembedded's validated setup.
            #
            # NOTE (2026-10-14): an explicit BUFG here was TRIED and is NOT a
            # fix for the breakout PHY-B failure -- the proven-working PHY-A
            # build shows the SAME profile (1 BUFGCTRL, no dedicated-routing
            # BUFG line), so the clock is buffered the same way on both. The
            # apparent "2 vs 1 BUFG" difference was an artifact of comparing a
            # full build against a USB_MINIMAL one (the audio domain adds one).
            m.d.comb += cd_usb.clk.eq(self.ulpi_clk_pin)

        # Until PLL is locked, hold sync/fast in reset. The usb domain
        # comes up when the PHY enables itself.
        reset = ~sys_locked
        m.submodules.reset_sync_sync = ResetSynchronizer(reset, domain="sync")
        m.submodules.reset_sync_fast = ResetSynchronizer(reset, domain="fast")

        return m
